class Router:
    """Routes LLM requests to priced models under per-tenant credit budgets."""

    def __init__(self):
        pass

    def add_model(self, name: str, price_per_token: int) -> None:
        raise NotImplementedError

    def set_budget(self, tenant: str, credits: int) -> None:
        raise NotImplementedError

    def remaining(self, tenant: str) -> int:
        raise NotImplementedError

    def route(self, tenant: str, model: str, prompt: str, timestamp: int) -> dict:
        raise NotImplementedError

ch-5.solution:
### Key insight
`route` is a pipeline: **validate → cache → candidates → charge → record**. Each level slots in
one stage without touching the others, which is exactly what interviewers look for.

### Reference implementation (all 4 levels)
```python
class Router:
    """Routes LLM requests to priced models under per-tenant credit budgets."""

    def __init__(self):
        self.prices: dict[str, int] = {}
        self.budgets: dict[str, int] = {}
        # Level 2
        self.fallbacks: dict[str, list[str]] = {}
        self.down_until: dict[str, int] = {}
        # Level 3
        self.cache_ttl: int | None = None
        self.cache: dict[tuple[str, str], tuple[str, int]] = {}
        # Level 4
        self.log: list[dict] = []
        self.spend: dict[str, int] = {}

    # ----- Level 1: models and budgets -----
    def add_model(self, name: str, price_per_token: int) -> None:
        if name in self.prices:
            raise ValueError(f"model {name!r} already exists")
        if price_per_token < 0:
            raise ValueError("price must be >= 0")
        self.prices[name] = price_per_token

    def set_budget(self, tenant: str, credits: int) -> None:
        if credits < 0:
            raise ValueError("budget must be >= 0")
        self.budgets[tenant] = credits
        self.spend.setdefault(tenant, 0)

    def remaining(self, tenant: str) -> int:
        return self.budgets[tenant]

    @staticmethod
    def count_tokens(prompt: str) -> int:
        return len(prompt.split())

    def route(self, tenant: str, model: str, prompt: str, timestamp: int) -> dict:
        if tenant not in self.budgets:
            raise KeyError(tenant)
        if model not in self.prices:
            raise KeyError(model)
        tokens = self.count_tokens(prompt)
        if tokens == 0:
            raise ValueError("empty prompt")

        # Level 3: cache lookup before any routing or charging
        key = (model, prompt)
        if self.cache_ttl is not None and key in self.cache:
            chosen, stored_at = self.cache[key]
            if timestamp < stored_at + self.cache_ttl:
                return self._record(tenant, model, timestamp,
                                    {"status": "cached", "model": chosen, "cost": 0})
            del self.cache[key]

        # Level 2: requested model first, then its fallback chain
        candidates = [model] + self.fallbacks.get(model, [])
        any_up = False
        for name in candidates:
            if timestamp < self.down_until.get(name, timestamp):
                continue
            any_up = True
            cost = tokens * self.prices[name]
            if cost <= self.budgets[tenant]:
                self.budgets[tenant] -= cost
                if self.cache_ttl is not None:
                    self.cache[key] = (name, timestamp)
                return self._record(tenant, model, timestamp,
                                    {"status": "ok", "model": name, "cost": cost})
        status = "rejected" if any_up else "unavailable"
        return self._record(tenant, model, timestamp,
                            {"status": status, "model": None, "cost": 0})

    # ----- Level 2: fallback -----
    def set_fallbacks(self, model: str, chain: list[str]) -> None:
        for name in [model] + list(chain):
            if name not in self.prices:
                raise KeyError(name)
        if model in chain:
            raise ValueError("a model cannot fall back to itself")
        self.fallbacks[model] = list(chain)

    def mark_down(self, model: str, until: int) -> None:
        if model not in self.prices:
            raise KeyError(model)
        self.down_until[model] = until

    # ----- Level 3: caching -----
    def enable_cache(self, ttl: int) -> None:
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.cache_ttl = ttl

    # ----- Level 4: metrics -----
    def _record(self, tenant: str, requested: str, timestamp: int, result: dict) -> dict:
        self.log.append({"tenant": tenant, "requested": requested,
                         "timestamp": timestamp, **result})
        self.spend[tenant] = self.spend.get(tenant, 0) + result["cost"]
        return result

    def metrics(self, start: int, end: int) -> dict:
        out = {"requests": 0, "ok": 0, "cached": 0, "rejected": 0, "unavailable": 0,
               "fallbacks": 0, "spend": 0, "by_model": {}}
        for entry in self.log:
            if not start <= entry["timestamp"] < end:
                continue
            out["requests"] += 1
            out[entry["status"]] += 1
            if entry["status"] == "ok":
                out["spend"] += entry["cost"]
                out["by_model"][entry["model"]] = out["by_model"].get(entry["model"], 0) + entry["cost"]
                if entry["model"] != entry["requested"]:
                    out["fallbacks"] += 1
        return out

    def top_tenants(self, n: int) -> list[tuple[str, int]]:
        if n <= 0:
            return []
        ranked = sorted(self.spend.items(), key=lambda item: (-item[1], item[0]))
        return ranked[:n]
```

### Design notes per level
- **Level 1:** two dicts. Validate tenant and model before computing cost; charge only on success.
- **Level 2:** candidates = `[model] + chain`. Skip down models and unaffordable ones. Track `any_up` so an all-down chain reports `"unavailable"` rather than `"rejected"`.
- **Level 3:** cache keyed by the *requested* model and the prompt, storing the *served* model. Lookup happens after validation (unknown tenants still raise) and before the budget check (hits are free). Expired entries are deleted lazily.
- **Level 4:** one `_record` helper wraps every return, so every outcome is logged with its timestamp and spend is updated in one place. Seeding `spend` in `set_budget` makes zero-spend tenants appear in `top_tenants`.

### Common pitfalls
- Charging before deciding the request succeeded, or charging on a cache hit.
- Treating the window as inclusive at `end` (it is half-open).
- Recursing into fallback chains of fallbacks (the brief forbids it).
- Checking the cache before validation, so a cached prompt lets an unknown tenant through.
- Refreshing the TTL on a hit.

