class ChatStore:
    """Per-conversation chat history that fits a model's token budget."""

    def __init__(self, max_tokens: int):
        pass

    def add(self, conversation_id: str, role: str, text: str, timestamp: int) -> int:
        raise NotImplementedError

    def context(self, conversation_id: str) -> list[dict]:
        raise NotImplementedError

    def token_count(self, conversation_id: str) -> int:
        raise NotImplementedError

ch-6.solution:
### Key insight
Keep **two views** of every conversation: the *active* messages the model may see and the
*folded* messages kept for search and retention. The summary is a pinned prefix that spends
budget first. Each level then touches one view.

### Reference implementation (all 4 levels)
```python
import re

ROLES = {"system", "user", "assistant"}


def _words(text: str) -> list[str]:
    return re.findall(r"[a-z0-9]+", text.lower())


class ChatStore:
    """Per-conversation chat history that fits a model's token budget."""

    def __init__(self, max_tokens: int):
        if max_tokens <= 0:
            raise ValueError("max_tokens must be > 0")
        self.max_tokens = max_tokens
        self.next_id = 1
        self.active: dict[str, list[dict]] = {}    # messages still in context
        self.archived: dict[str, list[dict]] = {}  # folded into a summary (Level 2)
        self.summaries: dict[str, dict] = {}        # one summary per conversation

    @staticmethod
    def tokens(text: str) -> int:
        return len(text.split())

    # ----- Level 1: token budget -----
    def add(self, conversation_id: str, role: str, text: str, timestamp: int) -> int:
        if role not in ROLES:
            raise ValueError(f"unknown role {role!r}")
        message = {"id": self.next_id, "role": role, "text": text, "timestamp": timestamp}
        self.next_id += 1
        self.active.setdefault(conversation_id, []).append(message)
        return message["id"]

    def context(self, conversation_id: str) -> list[dict]:
        summary = self.summaries.get(conversation_id)
        budget = self.max_tokens - (self.tokens(summary["text"]) if summary else 0)
        picked: list[dict] = []
        for message in reversed(self.active.get(conversation_id, [])):
            cost = self.tokens(message["text"])
            if cost > budget:
                break
            budget -= cost
            picked.append({"role": message["role"], "text": message["text"]})
        picked.reverse()
        if summary:
            picked.insert(0, {"role": "summary", "text": summary["text"]})
        return picked

    def token_count(self, conversation_id: str) -> int:
        total = sum(self.tokens(m["text"]) for m in self.active.get(conversation_id, []))
        summary = self.summaries.get(conversation_id)
        return total + (self.tokens(summary["text"]) if summary else 0)

    # ----- Level 2: summaries -----
    def summarize(self, conversation_id: str, upto_id: int, summary: str) -> int:
        messages = self.active.get(conversation_id, [])
        if not any(m["id"] == upto_id for m in messages):
            raise ValueError(f"message {upto_id} is not active in {conversation_id!r}")
        folded = [m for m in messages if m["id"] <= upto_id]
        self.active[conversation_id] = [m for m in messages if m["id"] > upto_id]
        self.archived.setdefault(conversation_id, []).extend(folded)
        self.summaries[conversation_id] = {"text": summary}
        return len(folded)

    # ----- Level 3: search -----
    def search(self, query: str, conversation_id: str | None = None, limit: int = 10) -> list[int]:
        terms = set(_words(query))
        if not terms:
            raise ValueError("query has no words")
        if limit <= 0:
            return []
        if conversation_id is None:
            ids = set(self.active) | set(self.archived)
        else:
            ids = {conversation_id}
        hits = []
        for cid in ids:
            for message in self.active.get(cid, []) + self.archived.get(cid, []):
                if terms <= set(_words(message["text"])):
                    hits.append(message["id"])
        return sorted(hits, reverse=True)[:limit]

    # ----- Level 4: retention and deletion -----
    def expire(self, before: int) -> int:
        removed = 0
        for store in (self.active, self.archived):
            for cid, messages in store.items():
                kept = [m for m in messages if m["timestamp"] >= before]
                removed += len(messages) - len(kept)
                store[cid] = kept
        return removed

    def delete_conversation(self, conversation_id: str) -> bool:
        existed = any(conversation_id in s for s in (self.active, self.archived, self.summaries))
        for store in (self.active, self.archived, self.summaries):
            store.pop(conversation_id, None)
        return existed
```

### Design notes per level
- **Level 1:** walk newest → oldest with a running budget and `break` at the first misfit; reverse at the end. O(n) per call.
- **Level 2:** `summarize` partitions active messages by id. The summary is always emitted, and its token cost is subtracted before filling (the budget can go negative, which simply admits no messages).
- **Level 3:** a regex tokenizer gives whole-word, case-insensitive matching; `terms <= words` checks "all words". Folded messages are included because search is about history, not context. For scale you'd build an inverted index `word → ids`.
- **Level 4:** retention applies to raw messages in both views; the summary is derived data and is kept. The global id counter never resets, so ids remain unique audit handles.

### Common pitfalls
- Skipping a too-big message and continuing to older ones (breaks "contiguous").
- Dropping the summary when it is larger than the budget.
- Substring search (`"rag" in "ragged"`).
- Forgetting folded messages in `search` or `expire`.
- Resetting ids when a conversation is deleted.

