class Leaderboard:
    """Game leaderboard: totals, ranks, time windows, pagination and moderation."""

    def __init__(self):
        pass

    def add_score(self, player: str, points: int, timestamp: int) -> int:
        raise NotImplementedError

    def score(self, player: str) -> int:
        raise NotImplementedError

    def top(self, n: int) -> list[tuple[str, int]]:
        raise NotImplementedError

    def rank(self, player: str) -> int | None:
        raise NotImplementedError

ch-7.solution:
### Key insight
Keep **events** as the source of truth and **totals** as a cache, and funnel every board
through one `_ordered` helper (sort + ban filter). Then windows, ranks, pages and moderation
all agree on ordering for free.

### Reference implementation (all 4 levels)
```python
class Leaderboard:
    """Game leaderboard: totals, ranks, time windows, pagination and moderation."""

    def __init__(self):
        self.totals: dict[str, int] = {}
        self.events: list[tuple[int, str, int]] = []  # (timestamp, player, points)
        self.banned: set[str] = set()                 # Level 4

    # ----- Level 1: scores and ranks -----
    def add_score(self, player: str, points: int, timestamp: int) -> int:
        if player in self.banned:
            raise PermissionError(f"{player} is banned")
        if not isinstance(points, int) or isinstance(points, bool) or points <= 0:
            raise ValueError("points must be a positive int")
        self.totals[player] = self.totals.get(player, 0) + points
        self.events.append((timestamp, player, points))
        return self.totals[player]

    def score(self, player: str) -> int:
        return self.totals.get(player, 0)

    def _ordered(self, totals: dict[str, int]) -> list[tuple[str, int]]:
        visible = [(p, s) for p, s in totals.items() if p not in self.banned]
        return sorted(visible, key=lambda item: (-item[1], item[0]))

    def top(self, n: int) -> list[tuple[str, int]]:
        return self._ordered(self.totals)[:max(n, 0)]

    def rank(self, player: str) -> int | None:
        for position, (name, _) in enumerate(self._ordered(self.totals), start=1):
            if name == player:
                return position
        return None

    # ----- Level 2: time windows -----
    def _window_totals(self, start: int, end: int) -> dict[str, int]:
        totals: dict[str, int] = {}
        for timestamp, player, points in self.events:
            if start <= timestamp < end:
                totals[player] = totals.get(player, 0) + points
        return totals

    def score_in_window(self, player: str, start: int, end: int) -> int:
        return self._window_totals(start, end).get(player, 0)

    def top_in_window(self, n: int, start: int, end: int) -> list[tuple[str, int]]:
        if start >= end:
            raise ValueError("start must be < end")
        return self._ordered(self._window_totals(start, end))[:max(n, 0)]

    # ----- Level 3: ties and pagination -----
    def _competition(self) -> list[tuple[int, str, int]]:
        rows, previous, place = [], None, 0
        for index, (name, total) in enumerate(self._ordered(self.totals), start=1):
            if total != previous:
                place, previous = index, total
            rows.append((place, name, total))
        return rows

    def rank_info(self, player: str) -> dict | None:
        rows = self._competition()
        mine = next((row for row in rows if row[1] == player), None)
        if mine is None:
            return None
        tied = [name for place, name, _ in rows if place == mine[0] and name != player]
        return {"rank": mine[0], "score": mine[2], "tied_with": tied}

    def page(self, page: int, size: int) -> dict:
        if page < 1 or size < 1:
            raise ValueError("page and size must be >= 1")
        rows = self._competition()
        start = (page - 1) * size
        return {
            "items": rows[start:start + size],
            "total_players": len(rows),
            "total_pages": (len(rows) + size - 1) // size,
        }

    # ----- Level 4: moderation -----
    def ban(self, player: str) -> bool:
        if player not in self.totals or player in self.banned:
            return False
        self.banned.add(player)
        return True

    def unban(self, player: str) -> bool:
        if player not in self.banned:
            return False
        self.banned.discard(player)
        return True

    def merge_players(self, source: str, target: str) -> int:
        if source == target:
            raise ValueError("cannot merge a player into itself")
        if source not in self.totals:
            raise KeyError(source)
        if source in self.banned or target in self.banned:
            raise PermissionError("cannot merge banned players")
        self.events = [(t, target if p == source else p, pts) for t, p, pts in self.events]
        self.totals[target] = self.totals.get(target, 0) + self.totals.pop(source)
        return self.totals[target]
```

### Design notes per level
- **Level 1:** `sorted(key=lambda (p, s): (-s, p))` gives score desc, name asc in one pass. Validate points strictly (bool is an int subclass in Python).
- **Level 2:** a window board is the same ordering over totals recomputed from events in `[start, end)`; O(E) per query. At scale you'd bucket events per day.
- **Level 3:** competition rank tracks the index where the current score first appeared. Pagination is plain slicing of the ranked rows; ranks are computed over the whole board before slicing, so a tie that straddles pages keeps its shared rank.
- **Level 4:** the ban filter lives inside `_ordered`, so every board respects it at once. Merging rewrites events (not just totals) so time windows stay correct.

### Common pitfalls
- Dense ranking (1, 1, 2) instead of competition ranking (1, 1, 3).
- Computing ranks per page instead of over the whole board.
- Accepting `True` or `1.5` as points.
- Moving only the total in a merge, which breaks window queries.
- Forgetting the ban filter in one of the five board methods.

