class FlagService:
    """Feature flags: targeting rules, percentage rollouts, audit log, prerequisites."""

    def __init__(self):
        pass

    def create_flag(self, name: str, default: bool) -> None:
        raise NotImplementedError

    def set_default(self, name: str, value: bool) -> None:
        raise NotImplementedError

    def add_rule(self, name: str, attribute: str, values: list, result: bool) -> None:
        raise NotImplementedError

    def evaluate(self, name: str, user: dict) -> bool:
        raise NotImplementedError

ch-8.solution:
### Key insight
Represent each flag as a **single config value** and make evaluation an ordered decision
list: prerequisites → rules → rollout → default. Snapshots of that one value give you the
audit log and rollback almost for free.

### Reference implementation (all 4 levels)
```python
import copy
import zlib


class FlagService:
    """Feature flags: targeting rules, percentage rollouts, audit log, prerequisites."""

    def __init__(self):
        self.flags: dict[str, dict] = {}
        self.audit: list[dict] = []  # Level 3: {"seq", "flag", "action", "config"}
        self.seq = 0

    def _flag(self, name: str) -> dict:
        if name not in self.flags:
            raise KeyError(name)
        return self.flags[name]

    def _log(self, name: str, action: str) -> None:
        self.seq += 1
        self.audit.append({"seq": self.seq, "flag": name, "action": action,
                           "config": copy.deepcopy(self.flags[name])})

    # ----- Level 1: flags and rules -----
    def create_flag(self, name: str, default: bool) -> None:
        if name in self.flags:
            raise ValueError(f"flag {name!r} already exists")
        self.flags[name] = {"default": default, "rules": [], "rollout": None, "prereqs": []}
        self._log(name, "create")

    def set_default(self, name: str, value: bool) -> None:
        self._flag(name)["default"] = value
        self._log(name, "set_default")

    def add_rule(self, name: str, attribute: str, values: list, result: bool) -> None:
        if not values:
            raise ValueError("a rule needs at least one value")
        self._flag(name)["rules"].append(
            {"attribute": attribute, "values": list(values), "result": result})
        self._log(name, "add_rule")

    def evaluate(self, name: str, user: dict) -> bool:
        flag = self._flag(name)
        # Level 4: prerequisites gate everything else
        for other, required in flag["prereqs"]:
            if self.evaluate(other, user) != required:
                return False
        for rule in flag["rules"]:
            if rule["attribute"] in user and user[rule["attribute"]] in rule["values"]:
                return rule["result"]
        # Level 2: rollout replaces the default for users no rule matched
        if flag["rollout"] is not None:
            if "id" not in user:
                raise ValueError("percentage rollout needs user['id']")
            return self.bucket(name, user["id"]) < flag["rollout"]
        return flag["default"]

    # ----- Level 2: percentage rollouts -----
    @staticmethod
    def bucket(name: str, user_id: str) -> int:
        return zlib.crc32(f"{name}:{user_id}".encode("utf-8")) % 100

    def set_rollout(self, name: str, percent: int | None) -> None:
        flag = self._flag(name)
        if percent is not None and not 0 <= percent <= 100:
            raise ValueError("percent must be between 0 and 100")
        flag["rollout"] = percent
        self._log(name, "set_rollout")

    # ----- Level 3: audit log and rollback -----
    def audit_log(self, name: str) -> list[dict]:
        self._flag(name)
        return [{"seq": e["seq"], "action": e["action"]} for e in self.audit if e["flag"] == name]

    def rollback(self, name: str, seq: int) -> None:
        self._flag(name)
        entry = next((e for e in self.audit if e["seq"] == seq and e["flag"] == name), None)
        if entry is None:
            raise ValueError(f"no audit entry {seq} for {name!r}")
        restored = copy.deepcopy(entry["config"])
        for other, _ in restored["prereqs"]:
            if self._depends_on(other, name):
                raise ValueError(f"rollback would create a cycle through {other!r}")
        self.flags[name] = restored
        self._log(name, "rollback")

    # ----- Level 4: prerequisites -----
    def _depends_on(self, name: str, target: str) -> bool:
        stack, seen = [name], set()
        while stack:
            current = stack.pop()
            if current == target:
                return True
            if current in seen:
                continue
            seen.add(current)
            stack.extend(other for other, _ in self.flags[current]["prereqs"])
        return False

    def add_prerequisite(self, name: str, other: str, required: bool) -> None:
        flag = self._flag(name)
        self._flag(other)
        if self._depends_on(other, name):
            raise ValueError(f"{name!r} -> {other!r} would create a cycle")
        flag["prereqs"].append((other, required))
        self._log(name, "add_prerequisite")

    def evaluate_all(self, user: dict) -> dict[str, bool]:
        return {name: self.evaluate(name, user) for name in sorted(self.flags)}
```

### Design notes per level
- **Level 1:** rules are a list, checked in insertion order; `attribute in user` guards the lookup so missing attributes never match.
- **Level 2:** hashing `flag:user_id` with CRC32 gives a stable bucket per user *per flag* (different flags slice users differently). The rollout replaces the default only when no rule matched, so explicit targeting still wins. Never use `hash()`: Python randomises string hashes per process.
- **Level 3:** a single `_log` helper called at the end of each mutation means failures (which raise earlier) are never logged. Snapshots are deep copies, so later edits can't mutate history.
- **Level 4:** prerequisites are edges in a dependency graph. Adding `name → other` creates a cycle exactly when `other` already reaches `name`; a DFS answers that. Rollback can re-introduce an old edge, so it runs the same check before applying.

### Common pitfalls
- Using Python's `hash()` for buckets (not stable across runs).
- Letting the rollout override rules, or the default override the rollout.
- Logging before validation, so failed calls appear in the audit log.
- Shallow-copying configs, so a later `add_rule` changes an old snapshot.
- Forgetting that `rollback` must restore prerequisites and can create cycles.
